# JobPilot helper kit. Every Bash call of a worker starts with:
#   cd "$JP_HOME" && source "$JP_ENGINE/jobkit.sh" <worker>
# Then use $AB (agent-browser wired to this worker's own browser window). Works in bash and zsh, incl. Git Bash on Windows.
# Personal values come from $JP_HOME/profile.env (generated from the dashboard profile); secrets from secrets.env.
W=${1:-1}
: "${JP_HOME:=$HOME/.jobpilot}"
AB="$JP_HOME/bin/ab$W"; export AB
[ -f "$JP_HOME/profile.env" ] && . "$JP_HOME/profile.env"
JP_PY=${JP_PY:-python3}
jlog(){ "$JP_PY" -m jobpilot.tools log "$@"; }     # jlog <url> <company> <role> <portal> <status> <notes>
jdone(){ "$JP_PY" -m jobpilot.tools done "$1"; }   # exit 0 if already applied/skipped
otp(){ "$JP_PY" -m jobpilot.tools otp "$@"; }      # otp --match greenhouse --len 8 | otp --match myworkday --link
creds(){ set -a; . "$JP_HOME/secrets.env"; set +a; }  # loads $email $password $password_strong $pan; never echo them
_nth(){ printf '%s\n' "$JP_COMPANIES" | tr '|' '\n' | sed -n "$(( $1 + 1 ))p"; }   # 0-based company from profile
_chars(){ printf '%s' "$1" | grep -o .; }

# nopicker: stop the page from opening the native file dialog (it never closes on its own in a real browser).
# Run after every page load/navigation on a page with an upload, BEFORE clicking anything; then upload with up.
nopicker(){ $AB eval '(()=>{if(window.__ja_guard)return "ok";window.__ja_guard=1;const isF=el=>el&&el.tagName==="INPUT"&&el.type==="file";const P=HTMLInputElement.prototype,c=P.click;P.click=function click(){if(this.type==="file")return;return c.call(this)};if(P.showPicker){const s=P.showPicker;P.showPicker=function showPicker(){if(this.type==="file")return;return s.call(this)}};if(window.showOpenFilePicker)window.showOpenFilePicker=function showOpenFilePicker(){return Promise.reject(new DOMException("The user aborted a request.","AbortError"))};document.addEventListener("click",e=>{const t=e.composedPath?e.composedPath()[0]:e.target;if(isF(t))e.preventDefault()},true);return "ok"})()' >/dev/null; }
# tclick <target> [fallback-js]: trusted --human click. Runs the JS fallback ONLY when the click definitely did not happen.
# Prints ok | fb:<js result> | maybe: <err> | fail: <err>; returns 0 | 0 | 2 | 1.
tclick(){ local o; o=$($AB click "$1" --human 2>&1) && { echo ok; return 0; }; if printf %s "$o" | grep -qiE 'os error (11|35|10035)|temporarily unavailable|could not be completed immediately|timed? ?out'; then echo "maybe: ${o:0:200}"; return 2; fi; if [ -n "$2" ]; then echo "fb:$($AB eval "$2")"; return 0; fi; echo "fail: ${o:0:200}"; return 1; }
# up '<css of input[type=file]>': guard + upload the active resume without ever opening the picker.
up(){ nopicker; $AB upload "${1:-input[type=file]}" "$JP_RESUME"; }
# formdump: every visible field in ONE call -> "f3 | select | Notice period* | current | options…" (keys for fillform)
formdump(){ $AB eval "$(cat "$JP_ENGINE/form_dump.js")" | sed 's/^"//; s/"$//; s/\\n/\n/g; s/\\"/"/g'; }
# fillform '<json>': fill many fields in ONE call, e.g. fillform '{"f1":"Ada","f4":"India","f7":"Yes","f9":true}'
# (keys from formdump, or CSS selectors). Prints ok/FAIL + read-back per field. Custom dropdowns still need clicks.
fillform(){ local b; b=$(printf %s "$1" | base64 | tr -d '\n'); $AB eval "($(cat "$JP_ENGINE/form_fill.js"))(JSON.parse(decodeURIComponent(escape(atob('$b')))))" | sed 's/^"//; s/"$//; s/\\n/\n/g; s/\\"/"/g'; }
# wfor '<js expr>' <max ms>: poll until expr is truthy (returns 0) or max reached (returns 1). Use instead of fixed waits.
wfor(){ local t=0; while [ $t -lt ${2:-8000} ]; do $AB eval "!!($1)" 2>/dev/null | grep -q true && return 0; $AB wait 350 >/dev/null; t=$((t+450)); done; return 1; }

# ---------- Workday ----------
WD_STEP='document.querySelector("[data-automation-id=progressBarActiveStep]")?.innerText'
WD_DUMP=$(cat <<'JS'
(()=>{const o=[];o.push("STEP: "+(document.querySelector("[data-automation-id=progressBarActiveStep]")?.innerText||"").replace(/\n/g," "));
document.querySelectorAll("[data-automation-id^=formField-]").forEach(f=>{const id=f.getAttribute("data-automation-id");const lab=(f.querySelector("label,legend")?.innerText||"").replace(/\n/g," ").slice(0,90);let v="";const inp=f.querySelectorAll("input:not([type=hidden]),textarea");inp.forEach(i=>{if(i.type==="radio"||i.type==="checkbox"){if(i.checked)v+="["+(i.labels?.[0]?.innerText||i.value)+"]"}else if(i.value)v+=i.value+";"});const btn=f.querySelector("button");if(btn&&btn.innerText.trim())v+=" btn:"+btn.innerText.trim().slice(0,40);const sel=Array.from(f.querySelectorAll("[data-automation-id=selectedItem]")).map(x=>x.innerText).join("|");if(sel)v+=" sel:"+sel;o.push(id+" | "+lab+" = "+v)});
o.push("ERRORS: "+Array.from(document.querySelectorAll("[data-automation-id=errorMessage]")).map(e=>e.innerText).join(" ; "));return o.join("\n")})()
JS
)
wdclick(){ tclick "[data-automation-id=\"$1\"]" "(()=>{const b=document.querySelector('[data-automation-id=\"$1\"]'); if(!b) return 'nf'; (b.parentElement.querySelector('[data-automation-id=click_filter]')||b).click(); return 'ok'})()"; }
wddump(){ $AB eval "$WD_DUMP" | sed 's/\\n/\n/g'; }
wdsignin(){ creds; $AB fill '[data-automation-id=email]' "$email" >/dev/null; $AB fill '[data-automation-id=password]' "$password" >/dev/null; wdclick signInSubmitButton; $AB wait 800 >/dev/null; wfor '!document.querySelector("[data-automation-id=password]") || document.querySelector("[data-automation-id=errorMessage],[role=alert]")' 9000; }
wdcreate(){ creds; $AB fill '[data-automation-id=email]' "$email" >/dev/null; $AB fill '[data-automation-id=password]' "$password" >/dev/null; $AB fill '[data-automation-id=verifyPassword]' "$password" >/dev/null; $AB eval "(()=>{const c=document.querySelector('[data-automation-id=createAccountCheckbox]'); if(c&&!c.checked) c.click(); return 'cb:'+!!c})()"; wdclick createAccountSubmitButton; $AB wait 800 >/dev/null; wfor '!document.querySelector("[data-automation-id=verifyPassword]") || document.querySelector("[data-automation-id=errorMessage],[role=alert]")' 10000; }
wderr(){ $AB eval '([...document.querySelectorAll("[data-automation-id=errorMessage],[role=alert]")].map(e=>e.innerText).join(" ; ")+" "+(document.body.innerText.match(/You may have entered the wrong[^\n]*/)||[""])[0]).trim()'; }
# wdpick <formField automation id suffix> <exact option text>
wdpick(){ $AB eval "(()=>{const b=document.querySelector('[data-automation-id=\"formField-$1\"] button'); b.scrollIntoView({block:'center'}); b.focus(); return 1})()" >/dev/null; $AB press Enter >/dev/null; wfor 'document.querySelector("[role=option]")' 3000; $AB wait 250 >/dev/null; local r=$($AB snapshot -i | grep -F "option \"$2\"" | tail -1 | grep -oE 'ref=e[0-9]+' | cut -d= -f2); if [ -n "$r" ]; then $AB click @$r >/dev/null; echo "$1=$2"; else echo "NOTFOUND $1 $2"; $AB eval '[...document.querySelectorAll("[role=option]")].map(o=>o.innerText.trim()).join(" | ")'; $AB press Escape >/dev/null; fi; $AB wait 300 >/dev/null; }
wdstep(){ $AB eval 'document.querySelector("[data-automation-id=progressBarActiveStep]")?.innerText.replace(/\n/g," ")'; }
# wdstart: from job apply page -> signed in (or account created) and on the resume step
wdstart(){ $AB eval '(()=>{const c=[...document.querySelectorAll("button")].find(b=>/^Decline|Accept Cookies/.test(b.innerText)); c?.click(); return 1})()' >/dev/null; wdclick autofillWithResume >/dev/null; wfor 'document.querySelector("[data-automation-id=signInLink],[data-automation-id=email],input[type=file]")' 7000; wdclick signInLink >/dev/null; wfor 'document.querySelector("[data-automation-id=password]") && !document.querySelector("[data-automation-id=verifyPassword]")' 4000; wdsignin; $AB wait 600 >/dev/null; local e=$(wderr); echo "signin: $e"; if echo "$e" | grep -qiE 'wrong|invalid|locked|not'; then wdclick createAccountLink >/dev/null; wfor 'document.querySelector("[data-automation-id=verifyPassword]")' 4000; wdcreate; echo "create: $(wderr)"; fi; wdstep; }
wdresume(){ nopicker; $AB upload 'input[type=file]' "$JP_RESUME" >/dev/null; wfor '/Successfully Uploaded/.test(document.body.innerText)' 12000; $AB eval 'document.body.innerText.match(/Successfully Uploaded!?/)?.[0]'; local s0=$($AB eval "$WD_STEP"); wdclick pageFooterNextButton >/dev/null; wfor "$WD_STEP !== $s0 && document.querySelector('[data-automation-id^=formField-]')" 12000; $AB wait 800 >/dev/null; wdstep; }
wdset(){ $AB eval "(()=>{const i=document.querySelector('[data-automation-id=\"formField-$1\"] input'); return !!i})()" | grep -q true && $AB fill "[data-automation-id=formField-$1] input" "$2" >/dev/null; }
wdradio(){ $AB eval "(()=>{const r=[...document.querySelectorAll('[data-automation-id=\"formField-$1\"] input[type=radio]')]; const n=r.find(i=>new RegExp('^$2','i').test((i.labels?.[0]?.innerText||'').trim())); n?.click(); return !!n})()"; }
# wdprompt <field> <search text> <option text>
wdprompt(){ $AB eval "(()=>{const i=document.querySelector('[data-automation-id=\"formField-$1\"] input'); i.scrollIntoView({block:'center'}); i.focus(); i.click(); return 1})()" >/dev/null; $AB keyboard type "$2" >/dev/null; $AB press Enter >/dev/null; wfor 'document.querySelector("[role=option]")' 4000; $AB wait 400 >/dev/null; local r=$($AB snapshot -i | grep -F "option \"$3" | head -1 | grep -oE 'ref=e[0-9]+' | cut -d= -f2); if [ -n "$r" ]; then $AB click @$r >/dev/null; $AB wait 500 >/dev/null; echo "$1 picked"; else echo "NOTFOUND $1"; $AB eval '[...document.querySelectorAll("[role=option]")].map(o=>o.innerText.trim()).join(" | ")'; fi; $AB press Escape >/dev/null; }
# wdinfo: My Information step from the profile (names, address, phone, state, title, previous-worker No)
wdinfo(){ wdset legalName--firstName "$JP_FIRST"; wdset legalName--lastName "$JP_LAST"; wdset addressLine1 "$JP_ADDR1"; [ -n "$JP_ADDR2" ] && wdset addressLine2 "$JP_ADDR2"; wdset city "$JP_CITY"; wdset postalCode "$JP_POSTAL"; wdset phoneNumber "$JP_PHONE"; wdradio candidateIsPreviousWorker No >/dev/null; [ -n "$JP_STATE" ] && $AB eval '(()=>{const b=document.querySelector("[data-automation-id=formField-countryRegion] button"); return b?b.innerText:"none"})()' | grep -q 'Select One' && wdpick countryRegion "$JP_STATE"; [ -n "$JP_TITLE" ] && $AB eval '(()=>{const b=document.querySelector("[data-automation-id=formField-legalName--title] button"); return b?b.innerText:"none"})()' | grep -q 'Select' && wdpick legalName--title "$JP_TITLE"; true; }
# wdexp: My Experience step: company names + locations from the profile, current job start date, degree, LinkedIn, resume
wdexp(){
 $AB eval '(()=>{const t=(sel,p)=>document.querySelectorAll(sel).forEach((e,i)=>e.setAttribute("data-ja",p+i)); t("[data-automation-id=formField-companyName] input","co"); t("[data-automation-id=formField-location] input","loc"); t("[data-automation-id=formField-roleDescription] textarea","rd"); return 1})()' >/dev/null
 local i c
 for i in 0 1 2 3; do c=$(_nth $i); [ -z "$c" ] && continue; $AB eval "!!document.querySelector('[data-ja=co$i]')" | grep -q true && $AB fill "[data-ja=co$i]" "$c" >/dev/null; $AB eval "!!document.querySelector('[data-ja=loc$i]')" | grep -q true && $AB fill "[data-ja=loc$i]" "$JP_WORK_CITY" >/dev/null; done
 local sid=$($AB eval '(document.querySelector("[data-automation-id=formField-startDate] input[id$=dateSectionMonth-input]")||{}).id||""' | tr -d '"')
 if [ -n "$sid" ] && [ -n "$JP_CUR_START_MONTH" ] && $AB eval "document.getElementById('$sid').value" | grep -q '""'; then $AB eval "document.getElementById('$sid').focus()" >/dev/null; for d in $(_chars "$JP_CUR_START_MONTH"); do $AB press $d >/dev/null; done; $AB eval "document.getElementById('${sid/Month/Year}').focus()" >/dev/null; for d in $(_chars "$JP_CUR_START_YEAR"); do $AB press $d >/dev/null; done; $AB press Tab >/dev/null; fi
 # resume parsers put the company name as the first line of the role description: remove that line
 local names="${JP_COMPANIES//\'/\\\'}|Company"
 for i in 0 1 2 3; do if $AB eval "(()=>{const t=document.querySelector('[data-ja=rd$i]'); return !!t && '$names'.split('|').some(n=>n&&t.value.startsWith(n))})()" | grep -q true; then $AB eval "(()=>{const t=document.querySelector('[data-ja=rd$i]'); t.focus(); t.setSelectionRange(0,t.value.indexOf('\n')+1); return 1})()" >/dev/null; $AB press Backspace >/dev/null; $AB press Tab >/dev/null; fi; done
 [ -n "$JP_DEGREE" ] && $AB eval '(()=>{const b=document.querySelector("[data-automation-id=formField-degree] button"); return b?b.innerText:"none"})()' | grep -q Select && { wdpick degree "$JP_DEGREE" | grep -q NOTFOUND && echo "degree: pick the closest option to '$JP_DEGREE' with wdpick degree '<option>'"; }
 [ -n "$JP_LINKEDIN" ] && $AB eval '!!document.querySelector("[data-automation-id=formField-linkedInAccount] input")' | grep -q true && $AB fill '[data-automation-id=formField-linkedInAccount] input' "$JP_LINKEDIN" >/dev/null
 $AB eval '!!document.querySelector("input[type=file]") && !/Successfully Uploaded/.test(document.body.innerText)' | grep -q true && { nopicker; $AB upload 'input[type=file]' "$JP_RESUME" >/dev/null; wfor '/Successfully Uploaded/.test(document.body.innerText)' 10000; }
 wddump | grep -E '^(formField|ERR)' | grep -v roleDesc | cut -c1-120
}
# wdtext <field> <text> : textarea/input via real keystrokes
wdtext(){ $AB eval "(()=>{const t=document.querySelector('[data-automation-id=\"formField-$1\"] textarea, [data-automation-id=\"formField-$1\"] input'); t.scrollIntoView({block:'center'}); t.focus(); t.select?.(); return 1})()" >/dev/null; $AB keyboard type "$2" >/dev/null; $AB press Tab >/dev/null; }
wdterms(){ $AB eval '(()=>{const c=document.querySelector("[data-automation-id=formField-acceptTermsAndAgreements] input"); if(c&&!c.checked) c.click(); return c?c.checked:"none"})()'; }
wdsubmit(){ local r=$($AB snapshot -i | grep -iE 'button "Submit( Application)?"' | head -1 | grep -oE 'ref=e[0-9]+' | cut -d= -f2); local rc=1; if [ -n "$r" ]; then tclick @$r; rc=$?; fi; [ $rc = 1 ] && wdclick pageFooterNextButton; wfor '/completed|congratulations/i.test(location.href) || /Application Submitted|Thank you/i.test(document.body.innerText) || document.querySelector("[data-automation-id=errorMessage]")' 15000; $AB wait 500 >/dev/null; $AB get url; $AB eval '(document.body.innerText.match(/(Application Submitted|Thank you[^\n]*)/i)||["?"])[0]'; }
wdsrc(){ if $AB eval '!!document.querySelector("[data-automation-id=formField-source] button[aria-haspopup=listbox]")' | grep -q true; then wdpick source "$JP_SOURCE" | grep -q NOTFOUND && wdpick source "$JP_SOURCE Jobs"; else wdprompt source "$JP_SOURCE" "$JP_SOURCE"; fi; $AB eval '(()=>{const b=document.querySelector("[data-automation-id=formField-phoneType] button"); return b?b.innerText:""})()' | grep -q Select && wdpick phoneType Mobile; true; }

# ---------- Greenhouse ----------
# ghcombo <css selector of combobox input> <typed text> <option text regex>
ghcombo(){ $AB eval "(()=>{const i=document.querySelector('$1'); i.scrollIntoView({block:'center'}); i.focus(); return 1})()" >/dev/null; $AB press ArrowDown >/dev/null; [ -n "$2" ] && $AB keyboard type "$2" >/dev/null; wfor 'document.querySelector("[role=option]")' 3000; $AB wait 400 >/dev/null; local r=$($AB snapshot -i | grep -E "option \"$3" | head -1 | grep -oE 'ref=e[0-9]+' | cut -d= -f2); if [ -n "$r" ]; then $AB click @$r >/dev/null; else echo "NF $1 [$3]:"; $AB eval '[...document.querySelectorAll("[role=option]")].filter(o=>!o.closest(".iti__country-list, .iti")).map(o=>o.innerText).slice(0,25).join(" | ")'; $AB press Escape >/dev/null; fi; $AB wait 300 >/dev/null; }
# ghbase: resume upload + name/email/country/phone/location from the profile
ghbase(){ nopicker; $AB upload "#resume" "$JP_RESUME" >/dev/null; $AB wait 4000 >/dev/null; $AB fill '#first_name' "$JP_FIRST" >/dev/null; $AB fill '#last_name' "$JP_LAST" >/dev/null; $AB fill '#email' "$JP_EMAIL" >/dev/null; [ -n "$JP_COUNTRY" ] && $AB eval '!!document.querySelector("#country")' | grep -q true && ghcombo '#country' "$JP_COUNTRY" "$JP_COUNTRY"; $AB fill '#phone' "$JP_PHONE" >/dev/null; [ -n "$JP_CITY" ] && $AB eval '!!document.querySelector("#candidate-location")' | grep -q true && ghcombo '#candidate-location' "$JP_CITY" "$JP_CITY"; true; }
# ghq: list question fields: id | type | label = value
ghq(){ $AB eval '[...document.querySelectorAll("[id^=question_]")].filter(i=>i.matches("input,textarea,select")&&i.type!="hidden").map(i=>{const l=(document.querySelector(`label[for="${i.id}"]`)?.innerText||i.labels?.[0]?.innerText||i.closest("fieldset")?.querySelector("legend")?.innerText||"").replace(/\n/g," ").slice(0,140); return i.id+"|"+i.type+(i.getAttribute("role")=="combobox"?"/combo":"")+"|"+l+"="+(i.type=="checkbox"?i.checked:i.value)}).join("\n")' | sed 's/\\n/\n/g'; }
ghsubmit(){ local r=$($AB snapshot -i | grep -iE 'button "Submit( Application)?"' | head -1 | grep -oE 'ref=e[0-9]+' | cut -d= -f2); local rc=1; if [ -n "$r" ]; then tclick @$r; rc=$?; fi; [ $rc = 1 ] && tclick 'button[type=submit], #submit_app' '(()=>{const b=[...document.querySelectorAll("button")].find(b=>/^Submit/i.test(b.innerText.trim())); if(!b) return "nf"; b.scrollIntoView({block:"center"}); b.click(); return "ok"})()'; $AB wait 1000 >/dev/null; wfor '/confirmation/.test(location.href) || /Thank you|security code/i.test(document.body.innerText) || document.querySelector(".helper-text--error")' 10000; $AB get url; $AB eval '(document.body.innerText.match(/(Thank you[^\n]*|security code[^\n]*|confirmation[^\n]*)/i)||["?"])[0]'; $AB eval '[...document.querySelectorAll("[class*=error], .helper-text--error")].map(e=>e.innerText).filter(Boolean).join(" ; ").slice(0,300)'; }
ghc(){ local o=$(ghcombo "$@"); if echo "$o" | grep -q '^NF'; then $AB press Escape >/dev/null; $AB wait 500 >/dev/null; ghcombo "$@"; fi; }

# ---------- Hirist ----------
hirist(){ $AB open "$1" >/dev/null; $AB wait 4000 >/dev/null; $AB get title; local r=$($AB snapshot -i | grep -E 'button "Apply"' | head -1 | grep -oE 'ref=e[0-9]+' | cut -d= -f2); $AB click @$r >/dev/null; $AB wait 4000 >/dev/null; $AB get url; $AB eval '[...document.querySelectorAll("[id^=question-],[id]")].filter(e=>/^(question-)?[0-9a-f]{24}$/.test(e.id)).map((q,i)=>{const t=q.querySelector("div div:nth-child(2)")?.innerText; const inp=q.querySelector("textarea")?"TEXT":q.querySelector("input[type=radio]")?"RADIO:"+[...q.querySelectorAll("input[type=radio]")].map(r=>r.labels?.[0]?.innerText).join("/"):q.querySelector("input")?"INPUT "+q.querySelector("input").type:q.querySelector("select")?"SELECT":"?"; return q.id+"|"+inp+"|"+t}).join("\n")' | sed 's/\\n/\n/g'; }
hset(){ $AB fill "[id=\"$1\"] textarea, [id=\"$1\"] input" "$2" >/dev/null; }
hradio(){ $AB eval "(()=>{const r=[...document.querySelectorAll('[id=\"$1\"] input[type=radio]')].find(r=>(r.labels?.[0]?.innerText||'').trim()=='$2'); (r.labels[0]).click(); return r.checked})()"; }
